/**
 * Fold the built app into one Worker module.
 *
 * The installer ships as an npm tarball and the client never builds anything,
 * so the built bundle has to travel inside the package like any other reviewed
 * source file. This writes worker/src/lib/app-assets.js exporting the JS and
 * CSS as strings; the Worker serves them at /app/assets/app.js and app.css.
 *
 * The generated file is COMMITTED on purpose. A prepublish build step is one
 * forgotten command away from shipping a tarball whose app is stale or absent,
 * and that failure would only show up on a client's machine.
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";

const here = dirname(fileURLToPath(import.meta.url));
const dist = join(here, "dist");
const js = join(dist, "app.js");
const css = join(dist, "app.css");
for (const f of [js, css]) {
  if (!existsSync(f)) throw new Error(`missing build output: ${f}. Run vite build first.`);
}
const jsText = readFileSync(js, "utf8");
const cssText = readFileSync(css, "utf8");
const stamp = createHash("sha256").update(jsText + cssText).digest("hex").slice(0, 12);

const out = `// GENERATED by frontend/build-to-worker.mjs — do not edit by hand.
// Source lives in frontend/src. Rebuild with: cd frontend && npm run build
// Bundle fingerprint: ${stamp}
export const APP_BUNDLE_ID = ${JSON.stringify(stamp)};
export const APP_JS = ${JSON.stringify(jsText)};
export const APP_CSS = ${JSON.stringify(cssText)};
`;
writeFileSync(join(here, "..", "worker", "src", "lib", "app-assets.js"), out);
console.log(`app-assets.js written (${(jsText.length / 1024).toFixed(1)}kB js, ${(cssText.length / 1024).toFixed(1)}kB css, id ${stamp})`);
